-- Initial schema and one-time import of the 13 existing repository publications.
-- Supabase runs this migration transactionally and records its version.
-- Abort rather than modify a pre-existing articles table.
-- No production configuration, credentials, or site design changes.
do $$ begin
  if to_regclass('public.articles') is not null then
    raise exception 'Existing articles table detected. Inspect its schema/data before migrating; no changes applied.';
  end if;
end $$;

create table public.articles (
  id uuid primary key default gen_random_uuid(),
  category text not null check (category in ('basketball', 'football', 'baseball', 'soccer')),
  title text not null,
  summary text not null default '',
  date date not null default current_date,
  ai boolean not null default true,
  status text not null default 'draft' check (status in ('draft', 'published')),
  sources text[] not null default '{}',
  created_at timestamptz not null default now()
);

-- Public reads only; writes go through the service-role key in the admin API routes.
alter table public.articles enable row level security;

create policy "Public can read published articles"
  on public.articles for select to anon, authenticated
  using (status = 'published');

-- No public insert/update/delete policies: only the service-role key (server) writes.

revoke all on public.articles from public, anon, authenticated;
grant select on public.articles to anon, authenticated;
grant all on public.articles to service_role;

-- Preserve the original thirteen published notes; no seed examples.
insert into public.articles (id, category, title, summary, date, ai, status, sources) values
('8d2e7c0d-9283-50b8-99ef-e7b3f7703785'::uuid, 'soccer', 'Leeds condemn alleged racist abuse of Jayden Bogle', 'Leeds'' 1-0 Premier League victory over Tottenham at Elland Road was followed by alleged racist abuse directed at defender Jayden Bogle on social media. Leeds condemned the alleged abuse. The win came on a late goal from Noah Okafor. The alleged abuse followed a tackle by Bogle on Tottenham''s Mathys Tel that drew no card — VAR saw no serious foul — and Tel left the match injured. Tottenham also condemned the abuse.', '2026-11-08'::date, true, 'published', array['https://www.espn.com/soccer/story/_/id/50422908/leeds-jayden-bogle-racist-abuse']::text[]),
('8d28ef0c-20e6-569a-bcf6-162a176a2c7c'::uuid, 'soccer', 'Manchester City''s third straight Premier League defeat', 'Nottingham Forest beat Manchester City 3-1 at the City Ground, with Liam Delap scoring twice. Goals from Cunha (6''), Delap (18'', 73'') and Cherki (52'') handed City their third straight Premier League defeat — their first run of three straight league losses since November-December 2024. Delap is a Manchester City academy graduate.', '2026-11-08'::date, true, 'published', array['https://www.espn.com/video/clip/_/id/50413322/man-city-fall-again-delap-double-inspires-forest']::text[]),
('423ee0a1-f806-55a5-b458-c8a35c2ab665'::uuid, 'soccer', 'Manchester United salvage 4-4 draw with Aston Villa but stay in relegation zone', 'Manchester United twice came from two goals down to draw 4-4 with Aston Villa at Old Trafford on Sunday. Substitutes Joshua Zirkzee (90+2'') and Patrick Dorgu (90+6'') scored in stoppage time after Villa had led 4-2. United stay 18th with 8 points in 10 games, one point from leaving the relegation zone, and will spend the international break in the bottom three — the first time in 40 years they have ended a day in the relegation zone at this stage of a season.', '2026-11-08'::date, true, 'published', array['https://www.espn.com/soccer/story/_/id/50410672/man-united-premier-league-relegation-zone']::text[]),
('3a22b285-7137-51bf-a6ee-d3997e61956f'::uuid, 'basketball', 'Man Arrested at LeBron James'' Home on Stalking Charges', 'A man was arrested Friday night at LeBron James'' Brentwood home on stalking charges after security spotted him on cameras around 9 p.m. and called police. The suspect claimed to be James'' son; the LAPD confirmed the arrest to ESPN. James was not home — he was playing in Cleveland — and the suspect did not enter the residence. His identity has not been disclosed.', '2026-11-07'::date, true, 'published', array['https://nypost.com/2026/11/07/us-news/stalker-arrested-at-lebron-james-la-home/','https://larrybrownsports.com/basketball/man-arrested-stalking-lebron-james-home/777497']::text[]),
('8a7c3d1d-532a-580f-94b8-ad79bf4ee92b'::uuid, 'basketball', 'Bucks'' 1-8 Start Faces a Test Against the Celtics', 'The Raptors beat the Bucks 121-107 on Friday at Fiserv Forum, Milwaukee''s fifth straight loss and its worst start since 1993-94. The 1-8 Bucks host the 7-2 Celtics on Sunday at 8:00 PM ET. Rookie Brayden Burries posted his first career double-double (21 points, 11 rebounds) in the Toronto loss, and Tyler Herro added 23 points and 10 assists.', '2026-11-07'::date, true, 'published', array['https://www.jsonline.com/story/sports/nba/bucks/2026/11/06/milwaukee-bucks-vs-toronto-raptors-nba-cup-injury-report-starters-odds/92640187007/','https://www.reuters.com/sports/basketball/raptors-come-back-beat-bucks-nba-cup-game--flm-2026-11-07/']::text[]),
('cce43e69-f039-55d7-93bd-123893a7ae8d'::uuid, 'basketball', 'Porzingis Steps Away From Basketball to Prioritize His Health', 'Kristaps Porzingis announced Friday he is stepping away from basketball to prioritize his health. He has played 0 games for Golden State this season. He did not say retirement — he remains under contract (2 years / $40M re-signed in June). He was diagnosed with POTS in 2025, and ESPN reported Golden State is withholding his $20M salary for not rendering services.', '2026-11-06'::date, true, 'published', array['https://www.reuters.com/sports/warriors-porzingis-stepping-away-basketball-prioritize-health-2026-11-07/','https://www.si.com/nba/as-kristaps-porzingis-steps-away-warriors-choice-between-four-ways-forward']::text[]),
('82816211-50fb-5b61-8ec1-0fbb7d38380f'::uuid, 'baseball', 'Blue Jays Distance Themselves From Santander''s Anti-Muslim Posts', 'After the November 3 elections, Anthony Santander reposted two videos to his Instagram story on Wednesday, November 4 — one saying "America voted for Sharia Last Night!" over an image of Michigan senator-elect Abdul El-Sayed, and another saying "Islam is not peaceful" — and deleted them Thursday morning. The Blue Jays issued a statement saying "Baseball is for everyone" that did not name Santander. No disciplinary action has been announced, and Santander has not apologized publicly.', '2026-11-06'::date, true, 'published', array['https://www.reuters.com/sports/jays-statement-anthony-santanders-anti-muslim-posts--flm-2026-11-06/']::text[]),
('2c0d7576-3e6c-5d97-8c24-d2ae20c6fe9b'::uuid, 'basketball', 'Luka Doncic Scores Season-High 53 as Lakers Beat Blazers 124-118', 'Luka Doncic scored a season-high 53 points (17/33 FG, 14/18 FT) with 5 rebounds and 5 assists as the Lakers beat the Trail Blazers 124-118 on Friday at Crypto.com Arena, lifting his scoring average to 40.1 points per game. It was his 11th career 50-point game and his fourth straight 40+ game — the first Laker to do that since Kobe Bryant in 2012. His 363 points through 9 games are the most since Wilt Chamberlain in 1962. The Lakers are 8-2.', '2026-11-06'::date, true, 'published', array['https://www.reuters.com/sports/basketball/luka-doncic-pours-53-lakers-rally-past-blazers--flm-2026-11-07/','https://www.espn.ph/nba/story/_/id/50406079/luka-doncic-stays-hot-scores-53-lead-lakers-blazers','https://www.thescore.com/nba/news/3647617/luka-doncic-scores-53-in-another-spectacular-offensive-game-carrying-lakers-past-blazers-124-118']::text[]),
('f23278d4-c701-5378-849c-7abe6a00ae4a'::uuid, 'soccer', 'Ronaldo Announces International Retirement After Rift With Coach Jorge Jesus', 'Cristiano Ronaldo announced his retirement from Portugal duty, effective after the November international break, following a fallout with coach Jorge Jesus. He leaves with 234 caps and 146 goals — both men''s international records — and continues his club career at Al-Nassr.', '2026-11-05'::date, true, 'published', array['https://www.reuters.com/sports/soccer/ronaldo-exits-portugal-stage-with-records-intact-farewell-clouded-by-rift-2026-11-05/']::text[]),
('bbb120ac-afbf-5b6e-84f1-625e1d92c29c'::uuid, 'basketball', 'Wembanyama Explodes for Career-High 52 in Spurs'' 112-111 Win Over Mavericks', 'Victor Wembanyama poured in a career-high 52 points with 24 rebounds and 8 blocks, hitting the game-winning free throw with 24.2 seconds left as the Spurs edged the Mavericks 112-111 for their sixth straight win.', '2026-11-05'::date, true, 'published', array['https://www.aljazeera.com/amp/sports/2026/11/5/wembanyama-pours-in-career-high-52-points-as-spurs-edge-mavericks-112-111','https://www.thescore.com/nba/news/3645709/wemby-goes-off-for-career-high-52-points-i-can-still-do-more']::text[]),
('30deac39-4948-5dee-8d50-b54a58ee2fa8'::uuid, 'baseball', 'Bo Naylor Testifies He Saw Nothing Unusual in Clase-Ortiz Pitch Case', 'Former Guardians catcher Bo Naylor testified Thursday in Brooklyn that he noticed nothing unusual about pitches from Emmanuel Clase or Luis Ortiz, who are accused of rigging pitches. Under cross-examination he said he didn''t know gamblers could bet on individual pitches until the case arose.', '2026-11-06'::date, true, 'published', array['https://www.sportsnet.ca/mlb/article/catcher-bo-naylor-testifies-he-didnt-know-gamblers-bet-on-individual-pitches/','https://www.covers.com/industry/nothing-suspicious-says-ex-guardian-bo-naylor-in-clase-ortiz-hearing-nov-6-2026']::text[]),
('698f989b-db3d-58d5-b414-d1ddf4cf4720'::uuid, 'football', 'Jaguars Rout Shorthanded Ravens 33-10 in Dominant Display', 'The Jaguars crushed the short-handed Ravens 33-10 for their fifth win in six games. Trevor Lawrence threw for 242 yards and a touchdown, Cam Little kicked four field goals, and Jacksonville''s defense forced three turnovers while holding Derrick Henry to 57 yards.', '2026-11-06'::date, true, 'published', array['https://www.reuters.com/sports/nfl/jaguars-limit-quarterback-starved-ravens-227-yards-one-sided-win--flm-2026-11-06/']::text[]),
('aa239ce3-1f51-5cc4-94df-e97d4a70dc69'::uuid, 'baseball', 'MLB Pitch-Rigging Trial Opens as Baseball Faces Integrity Test', 'The federal trial of Guardians pitchers Emmanuel Clase and Luis Ortiz began Monday in Brooklyn, with both accused of rigging pitches as part of a betting scheme. A major MLB storyline moves from the diamond to the courtroom.', '2026-11-02'::date, true, 'published', array[]::text[]);
